from lib import *
S = SS('g27')
steps = [
    step("合法用法:*(*uint64)(unsafe.Pointer(&f)) 读 float64 1.5 的位模式 = 0x3ff8000000000000,与 math.Float64bits(f) 相等;指针运算在一个表达式里完成:unsafe.Add(&arr[0], 8) 读到 30,uintptr(&arr[0]) + 3*Sizeof 读到 40;unsafe.Offsetof:A = 0、B = 8、C = 16,Sizeof(Rec) = 24,Alignof(Rec) = 8,用 Offsetof 访问字段 C 读到 7;unsafe.String、unsafe.Slice、unsafe.StringData 在 []byte 与字符串之间互转。", t=tl(S(1)), done=lidx(S(1), '模式 1', '模式 3', 'unsafe.Offsetof', '用 Offsetof 访问字段'), mark=lidx(S(1), 'unsafe.String / unsafe.Slice'), kv=KV([['类型转换', '*(*uint64)(unsafe.Pointer(&f)) = 0x3ff8000000000000'], ['指针运算', 'unsafe.Add(p, 8) 或同一个表达式里的 uintptr 运算'], ['字段偏移', 'Offsetof:0、8、16;Sizeof 24'], ['字符串与字节切片', 'unsafe.String / Slice / StringData']], ['指针运算'])),
    step("uintptr 不是引用:局部变量 x 的地址在递归把栈撑大之后变了(增长前 0xcbe0、增长后 0xfbe0,不相等),但用 unsafe.Pointer 保存的 p 被运行时改写,读 x 还是 42,p == &x;而用 uintptr 保存的旧地址已经指向被释放的旧栈。堆上的对象(赋给了全局变量)3 次 GC 之后地址不变;栈上不逃逸的局部变量 3 次 GC 之后地址变了(GC 会收缩栈)。", t=tl(S(2)), done=lidx(S(2), '局部变量 x 的地址', '用增长前保存的 unsafe.Pointer p'), mark=lidx(S(2), '堆上对象', '栈上的局部变量'), kv=KV([['递归撑大栈', '栈被拷贝到新位置,x 的地址变了'], ['unsafe.Pointer 变量', '运行时在拷贝栈时同步改写,仍然有效'], ['uintptr 变量', '只是个数字,变成旧栈上的悬空地址'], ['堆对象', '3 次 GC 不动(当前实现,不保证)'], ['栈变量', 'GC 之后地址也可能变(栈收缩)']], ['uintptr 变量'])),
    step("窥探未导出字段(依赖标准库内部布局,脆弱):bytes.Buffer 的第一个字段是底层 []byte。*(*[]byte)(unsafe.Pointer(&buf)) 读出 \"peek\",长度 4、容量 64,与 buf.Len() = 4、buf.Cap() = 64 一致。库一旦调整字段顺序,这段代码就会静默读错。", t=tl(S(3)), mark=lidx(S(3), '*(*[]byte)(unsafe.Pointer(&buf))'), kv=KV([['读到的内容', '\"peek\",len 4,cap 64'], ['与公开方法对照', 'buf.Len() = 4,buf.Cap() = 64'], ['风险', '依赖字段顺序,标准库可以随时改']], ['风险'])),
    step("go vet 与 checkptr:uintptr 存进变量加 8 再转回指针:go vet 报 possible misuse of unsafe.Pointer,默认编译运行不出错,加 -gcflags=all=-d=checkptr=1 后 fatal error: checkptr: pointer arithmetic result points to invalid allocation(退出码 2);堆上字节切片从 b[1] 起转成含指针的 *[1]*int:vet 无警告,默认运行得到 nil,checkptr 报 misaligned pointer conversion;同样的未对齐转换但目标是 *int64:checkptr 也不报;unsafe.Add 越过堆上 16 字节切片末尾 100 字节:vet 无警告,checkptr 报 pointer arithmetic result points to invalid allocation;堆上 *[4]byte 转 *[8]byte:vet 与 checkptr 都不报。", t=tl(S(4)), done=lidx(S(4), 'uintptr 存进变量', '同样的未对齐转换'), mark=lidx(S(4), 'misaligned pointer conversion', 'pointer arithmetic result points to invalid allocation', '把堆上的 *[4]byte'), kv=KV([['uintptr 往返 + 加法', 'vet 警告;checkptr:invalid allocation'], ['未对齐 → 含指针的类型', 'checkptr:misaligned pointer conversion'], ['未对齐 → *int64', 'checkptr 不报'], ['unsafe.Add 越界(堆)', 'checkptr:invalid allocation'], ['*[4]byte → *[8]byte', 'vet、checkptr 都不报']], ['未对齐 → *int64'])),
]
A = mkartg('g27', 27, 'Go,unsafe,unsafe.Pointer,uintptr,checkptr,真实验证,动画演示',
    '在 Go 1.27.1 里验证 unsafe.Pointer 的用法与风险:合法的类型转换、unsafe.Add 与 Offsetof;uintptr 不是引用——递归撑大 goroutine 栈后局部变量的地址变了,unsafe.Pointer 被同步改写而 uintptr 变成悬空地址,堆对象 3 次 GC 后地址不变;go vet 的 unsafeptr 警告与 -d=checkptr=1 的运行时检查(未对齐、指针运算越界会 fatal,目标类型不含指针的未对齐与跨原对象的转换不报)。',
    'unsafe 包让你绕过类型系统,但规范里有一套“合法模式”,违反了在大多数情况下“碰巧能跑”,直到栈被搬动或 GC 改变时才出错。这篇用实验展示:合法写法、uintptr 为什么不是指针(栈会搬)、窥探内部布局的脆弱,以及 go vet 与 checkptr 能抓住哪些误用、抓不住哪些。',
    [('0xcbe0 → 0xfbe0', '递归撑大栈之后同一个局部变量的地址(低 16 位),旧的 uintptr 已悬空'), ('3 种错误', 'checkptr 报了:uintptr 往返、含指针类型的未对齐转换、堆上 unsafe.Add 越界'), ('不报', '目标为 *int64 的未对齐转换、*[4]byte 转 *[8]byte,checkptr 与 vet 都没发现')],
    [('合法模式', '<p><code>unsafe</code> 文档列出的合法模式在实验里都能得到预期结果:同大小类型间的转换(<code>float64</code> 与 <code>uint64</code> 的位模式)、在<b>同一个表达式</b>里把 <code>unsafe.Pointer</code> 转成 <code>uintptr</code> 做加法再转回来、用 <code>unsafe.Add</code> 做指针偏移、用 <code>Offsetof</code> 访问字段。新代码优先用 <code>unsafe.Add</code> 而不是 <code>uintptr</code> 运算。</p>'),
     ('uintptr 与栈', '<p><code>uintptr</code> 只是一个整数,GC 与栈拷贝都不认识它。goroutine 栈增长时运行时会把整个栈搬到新地址,并把栈上所有指针(包括 <code>unsafe.Pointer</code> 变量)改写成新地址;<code>uintptr</code> 变量不会被改写,变成指向旧栈的悬空数字。堆对象在当前实现里不会被 GC 移动,但语言规范并没有保证这一点——所以“把地址存成整数以后再用”是一种在今天碰巧能用、明天可能出错的写法。栈上变量在 GC 之后地址也可能变(栈收缩),这是实验里观察到的。</p>'),
     ('窥探内部布局', '<p>用 <code>unsafe</code> 读标准库类型的未导出字段能工作,是因为布局恰好如此;它与库的内部实现耦合,升级一个版本就可能静默读错。能用公开方法就不要这样。</p>'),
     ('vet 与 checkptr', '<p><code>go vet</code> 的 unsafeptr 检查只抓“<code>uintptr</code> 转回 <code>unsafe.Pointer</code>”这一类。运行时的 <code>checkptr</code>(<code>-race</code> 会自动打开,也可以用 <code>-gcflags=all=-d=checkptr=1</code> 单独打开)能抓到更多:指针运算越界、含指针类型的未对齐转换。从实验也看到它不是万能的:目标类型不含指针的未对齐转换、把 4 字节对象转成 8 字节数组类型的情形,都没有被报告(后一种我推测是因为 4 字节的对象实际落在 8 字节的分配块里,没有验证)。把 checkptr 当作测试时的辅助,而不是正确性的证明。</p>')],
    steps,
    [ENV_G + '。所有输出来自真实运行;栈增长靠一个递归函数(每层 512 字节),地址只打印低 16 位;checkptr 用 -gcflags=all=-d=checkptr=1 编译;堆上的对象用赋给全局变量的方式确保逃逸',
     '没有验证:checkptr 的完整检查清单(只试了 4 种误用)、unsafe 在 cgo 指针传递规则下的要求、reflect.SliceHeader / StringHeader 的废弃替代用法、amd64 上的栈增长地址、被 GC 移动的可能(规范不保证,当前实现没有观察到)'],
    'unsafe.Pointer')
